@Transactional(rollbackFor = Exception.class)
public void pay(String orderId, Money amount) {
    orderRepository.lockForUpdate(orderId);   // гонка списаний
    accountRepository.debit(amount);
    eventRepository.append(new OrderPaid(orderId));
} // commit или rollback — на выходе из метода

@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock OrderRepository repo;
    @InjectMocks OrderService service;

    @Test
    void rejectsOverdraft() {
        when(repo.find(ORDER_ID)).thenReturn(orderWithBalance(100));
        assertThrows(InsufficientFunds.class,
            () -> service.transfer(ORDER_ID, 200));
        verify(repo, never()).save(any());
    }
}
